/// Run a tiny query over records and return the 0-based indices of the
/// selected records, in result order.
/// Each record is a vector of (field, value) pairs; if a field appears more
/// than once in a record, its first value counts. The query is a sequence
/// of tokens separated by whitespace (leading and trailing whitespace is
/// allowed). Its grammar, where every part is optional but the parts must
/// come in this order:
///     [COND {"and" COND}] ["order" "by" FIELD ["desc"]] ["limit" N]
/// COND is exactly three tokens FIELD OP INT, where OP is one of
/// = != < <= > >=. FIELD is one or more of the characters a-z and _, and is
/// not one of the keywords and, order, by, desc, limit. INT is an optional
/// "-" followed by 1 to 9 digits; N is 1 to 9 digits with no sign.
/// A record is selected if it satisfies every COND; a COND on a field the
/// record does not have is false, for every OP including !=. With no COND,
/// every record is selected. "order by FIELD" sorts the selected records
/// by that field ascending ("desc": descending); records lacking the field
/// come after all records that have it; records with equal values, and
/// records lacking the field, keep their original relative order. Without
/// "order by", the original order is kept. "limit N" keeps the first N.
/// If the query does not match the grammar, return None.
/// >>> run_query(vec![vec![(String::from("age"), 30)], vec![(String::from("age"), 20)], vec![(String::from("id"), 1)]], String::from("age >= 20 order by age"))
/// Some(vec![1, 0])
/// >>> run_query(vec![vec![(String::from("a"), 1)], vec![(String::from("a"), 2), (String::from("a"), 9)], vec![(String::from("a"), 3)]], String::from("order by a desc limit 2"))
/// Some(vec![2, 1])
fn run_query(records: Vec<Vec<(String, i64)>>, query: String) -> Option<Vec<usize>> {
    const KEYWORDS: [&str; 5] = ["and", "order", "by", "desc", "limit"];
    const OPS: [&str; 6] = ["=", "!=", "<", "<=", ">", ">="];
    let is_field = |t: &str| !t.is_empty() && !KEYWORDS.contains(&t) && t.chars().all(|c| c == '_' || c.is_ascii_lowercase());
    let is_digits = |t: &str| (1..=9).contains(&t.len()) && t.chars().all(|c| c.is_ascii_digit());
    let toks: Vec<&str> = query.split_whitespace().collect();
    let n = toks.len();
    let mut i = 0;
    let mut conds: Vec<(&str, &str, i64)> = Vec::new();
    if i < n && toks[i] != "order" && toks[i] != "limit" {
        loop {
            if i + 3 > n || !is_field(toks[i]) || !OPS.contains(&toks[i + 1]) {
                return None;
            }
            let v = toks[i + 2];
            if !is_digits(v.strip_prefix('-').unwrap_or(v)) {
                return None;
            }
            conds.push((toks[i], toks[i + 1], v.parse().ok()?));
            i += 3;
            if i < n && toks[i] == "and" {
                i += 1;
            } else {
                break;
            }
        }
    }
    let (mut order, mut desc, mut limit) = (None, false, None);
    if i < n && toks[i] == "order" {
        if i + 2 >= n || toks[i + 1] != "by" || !is_field(toks[i + 2]) {
            return None;
        }
        order = Some(toks[i + 2]);
        i += 3;
        if i < n && toks[i] == "desc" {
            desc = true;
            i += 1;
        }
    }
    if i < n && toks[i] == "limit" {
        if i + 1 >= n || !is_digits(toks[i + 1]) {
            return None;
        }
        limit = Some(toks[i + 1].parse::<usize>().ok()?);
        i += 2;
    }
    if i != n {
        return None;
    }
    let lookup = |rec: &Vec<(String, i64)>, field: &str| rec.iter().find(|p| p.0 == field).map(|p| p.1);
    let mut sel: Vec<usize> = (0..records.len())
        .filter(|&j| {
            conds.iter().all(|&(f, op, x)| match lookup(&records[j], f) {
                None => false,
                Some(v) => match op {
                    "=" => v == x,
                    "!=" => v != x,
                    "<" => v < x,
                    "<=" => v <= x,
                    ">" => v > x,
                    _ => v >= x,
                },
            })
        })
        .collect();
    if let Some(f) = order {
        let (mut have, missing): (Vec<usize>, Vec<usize>) = sel.into_iter().partition(|&j| lookup(&records[j], f).is_some());
        have.sort_by(|&a, &b| {
            let (va, vb) = (lookup(&records[a], f), lookup(&records[b], f));
            if desc { vb.cmp(&va) } else { va.cmp(&vb) }
        });
        sel = have.into_iter().chain(missing).collect();
    }
    if let Some(l) = limit {
        sel.truncate(l);
    }
    Some(sel)
}
